if (job.status === 'error') {
  var nKept = (job.saved || []).length;
  var mid = job.progress || {};
  if (nKept > 0) {
    msg((job.hint && /kept /.test(job.hint) ? job.hint : ('Pull interrupted at ' + (mid.done || '?') + '/' + (mid.total || codes) +
      (mid.code ? (' · ' + mid.code) : '') +
      ' — kept ' + nKept + ' PDF(s) under PDFs by apartment. Pull again to continue; already saved codes are skipped.')),
      true);
    var vaultKeep = document.getElementById('pi-vault-heading') || document.getElementById('pi-leased-list');
    if (vaultKeep) try { vaultKeep.scrollIntoView({ block: 'start' }); } catch (eScroll) {}
    return;
  }
  var midBit = (mid.done && mid.total) ? (' (stopped at ' + mid.done + '/' + mid.total + (mid.code ? (' · ' + mid.code) : '') + ')') : '';
  var hintBit = job.hint && String(job.hint).indexOf('Pulling Airbnb') < 0 ? (' — ' + job.hint) : '';
  msg((job.error && job.error !== 'Pull failed' ? job.error : 'Pull interrupted') + hintBit + midBit + (errTxt ? (' · ' + errTxt) : ''), false);
  return;
}
